javascript:(async function(){const O=document.createElement('div');O.style.cssText='position:fixed;top:20px;right:20px;z-index:99999;background:#1a1a2e;color:#0f0;padding:12px 20px;border-radius:8px;font:14px monospace;box-shadow:0 4px 20px rgba(0,0,0,.6);border:1px solid #0f0';O.textContent='⏳ Extraindo dados da pauta...';document.body.appendChild(O);function norm(d){if(!d)return'';const n=d.replace(/\D/g,'');if(n.length===14)return n.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/,'$1.$2.$3/$4-$5');if(n.length===11)return n.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/,'$1.$2.$3-$4');return d;}try{const B=location.origin;const r1=await fetch(B+'/audapi/rest/pje/audpje/pautas?dataInicio=2026-07-21&dataFim=2026-07-21&orgaoJulgador=187',{credentials:'include',headers:{'Accept':'application/json'}});const j1=await r1.json();const lista=Array.isArray(j1)?j1:(j1.content||j1.resultado||j1.pautas||[]);const filtradas=lista.filter(p=>{const t=(p.tipoAudiencia||'').toLowerCase();return !t.includes('julgamento')&&!t.includes('encerramento');});const ids=[...new Set(filtradas.map(p=>p.idProcesso).filter(Boolean))];const cache={};const API=B+'/pje-comum-api/api';for(let i=0;i<ids.length;i+=5){const lote=ids.slice(i,i+5);const res=await Promise.all(lote.map(async id=>{try{const r=await fetch(API+'/processos/id/'+id+'/partes',{credentials:'include',headers:{'Accept':'application/json'}});if(!r.ok)return{id,ok:false};return{id,ok:true,data:await r.json()};}catch(e){return{id,ok:false};}}));for(const r of res){if(r.ok&&r.data){const partes=[];for(const polo of['ATIVO','PASSIVO']){for(const pt of(r.data[polo]||[])){const advs=(pt.representantes||[]).map(a=>a.nome+' OAB/'+(a.numeroOab||'')).join('; ');partes.push({nome:pt.nome||'',doc:norm(pt.documento||''),tipo:pt.tipo||'',polo,adv:advs});}}cache[r.id]=partes;}else{cache[r.id]=[];}}}const linhas=[];for(const p of filtradas){const partes=cache[p.idProcesso]||[];const ativos=partes.filter(pt=>pt.polo==='ATIVO');const passivos=partes.filter(pt=>pt.polo==='PASSIVO');const conpag=(p.siglaClasseJudicial||'')==='ConPag'?' ⚠️ConPag':'';const hora=(p.dataAudiencia||'').slice(11,16);const tipo=p.tipoAudiencia||'';linhas.push([p.numeroProcesso+conpag,hora,tipo,ativos.map(pt=>pt.nome+' '+pt.doc+(pt.adv?' ['+pt.adv+']':'')).join(' | '),passivos.map(pt=>pt.nome+' '+pt.doc+(pt.adv?' ['+pt.adv+']':'')).join(' | ')].join('\t'));}const txt='Processo\tHora\tTipo\tPolo Ativo\tPolo Passivo\n'+linhas.join('\n');await navigator.clipboard.writeText(txt);O.textContent='✅ Dados extraídos e copiados, cole no AudiCheck!';O.style.color='#0f0';setTimeout(()=>O.remove(),5000);}catch(e){O.textContent='❌ Erro: '+e.message;O.style.color='#f44';setTimeout(()=>O.remove(),8000);}})();
